"use strict";

// Pure geometry helpers for the canvas MCP server. Boards generated by a model
// arrive as a graph, not as coordinates, so these layouts turn an outline into
// readable cards: a layered tree, a two-sided mind map, or a grid.
//
// Positions are rounded to whole pixels. Sizes stay inside the clamps that
// Prism's sanitizer enforces, so a layout can never produce a document Prism
// would silently rewrite.

const DEFAULT_H_GAP = 90;
const DEFAULT_V_GAP = 34;
const DEFAULT_PADDING = 60;
const MIN_CARD_WIDTH = 120;
const MAX_CARD_WIDTH = 1200;

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function round(value) {
  return Math.round(value);
}

function isCjkChar(code) {
  return (
    (code >= 0x2e80 && code <= 0x9fff) ||
    (code >= 0xac00 && code <= 0xd7af) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xff00 && code <= 0xffef)
  );
}

// Rough visual width in "characters": CJK glyphs count as two Latin characters.
function visualLength(text) {
  let total = 0;
  for (const char of String(text ?? "")) {
    total += isCjkChar(char.codePointAt(0)) ? 2 : 1;
  }
  return total;
}

function autoNodeHeight(node) {
  const width = clamp(Number(node.width) || 220, MIN_CARD_WIDTH, MAX_CARD_WIDTH);
  const fontSize = clamp(Number(node.fontSize) || 14, 10, 48);
  const usable = Math.max(48, width - 24);
  const charsPerLine = Math.max(4, usable / (fontSize * 0.62));
  const lines = String(node.text ?? "")
    .split("\n")
    .reduce((count, line) => count + Math.max(1, Math.ceil(visualLength(line) / charsPerLine)), 0);
  const height = 20 + lines * fontSize * 1.5;
  return round(clamp(height, 44, 1200));
}

function buildGraph(nodes, edges) {
  const byId = new Map(nodes.map((node) => [node.id, node]));
  const children = new Map(nodes.map((node) => [node.id, []]));
  const parent = new Map();
  const neighbors = new Map(nodes.map((node) => [node.id, []]));
  for (const edge of edges) {
    if (!edge || edge.source === edge.target) continue;
    if (!byId.has(edge.source) || !byId.has(edge.target)) continue;
    if (parent.has(edge.target)) continue;
    parent.set(edge.target, edge.source);
    children.get(edge.source).push(edge.target);
    neighbors.get(edge.source).push(edge.target);
    neighbors.get(edge.target).push(edge.source);
  }
  return { byId, children, parent, neighbors };
}

function measureSubtree(id, children, nodesById, gap, axis) {
  const cache = new Map();
  const visiting = new Set();
  const visit = (nodeId) => {
    if (cache.has(nodeId)) return cache.get(nodeId);
    const node = nodesById.get(nodeId);
    if (!node) return 0;
    const own = axis === "height" ? node.height : node.width;
    if (visiting.has(nodeId)) return own;
    visiting.add(nodeId);
    const kids = (children.get(nodeId) || []).filter((kid) => nodesById.has(kid));
    if (kids.length === 0) {
      visiting.delete(nodeId);
      cache.set(nodeId, own);
      return own;
    }
    let total = 0;
    for (const kid of kids) total += visit(kid);
    total += gap * (kids.length - 1);
    const value = Math.max(own, total);
    visiting.delete(nodeId);
    cache.set(nodeId, value);
    return value;
  };
  return visit(id);
}

function layoutTree(nodes, edges, options = {}) {
  if (nodes.length === 0) return;
  const direction = options.direction === "TB" ? "TB" : "LR";
  const hGap = Number(options.hGap) > 0 ? Number(options.hGap) : DEFAULT_H_GAP;
  const vGap = Number(options.vGap) > 0 ? Number(options.vGap) : DEFAULT_V_GAP;
  const nodesById = new Map(nodes.map((node) => [node.id, node]));
  const { children, parent } = buildGraph(nodes, edges);

  const roots = nodes.filter((node) => !parent.has(node.id));
  if (roots.length === 0) roots.push(nodes[0]);

  const depth = new Map();
  const component = new Map();
  const visited = new Set();
  const components = [];
  for (const root of roots) {
    if (visited.has(root.id)) continue;
    const index = components.length;
    components.push(root.id);
    const queue = [{ id: root.id, level: 0 }];
    while (queue.length > 0) {
      const { id, level } = queue.shift();
      if (visited.has(id)) continue;
      visited.add(id);
      depth.set(id, level);
      component.set(id, index);
      for (const kid of children.get(id) || []) {
        if (!visited.has(kid)) queue.push({ id: kid, level: level + 1 });
      }
    }
  }
  // Cycles leave nodes without a root; each unvisited node starts its own column.
  for (const node of nodes) {
    if (visited.has(node.id)) continue;
    const index = components.length;
    components.push(node.id);
    const queue = [{ id: node.id, level: 0 }];
    while (queue.length > 0) {
      const { id, level } = queue.shift();
      if (visited.has(id)) continue;
      visited.add(id);
      depth.set(id, level);
      component.set(id, index);
      for (const kid of children.get(id) || []) {
        if (!visited.has(kid)) queue.push({ id: kid, level: level + 1 });
      }
    }
  }

  const mainSizeByLevel = new Map();
  for (const node of nodes) {
    const level = depth.get(node.id) || 0;
    const size = direction === "LR" ? node.width : node.height;
    mainSizeByLevel.set(level, Math.max(mainSizeByLevel.get(level) || 0, size));
  }
  const mainStart = new Map();
  let mainCursor = 0;
  for (const level of Array.from(mainSizeByLevel.keys()).sort((a, b) => a - b)) {
    mainStart.set(level, mainCursor);
    mainCursor += mainSizeByLevel.get(level) + (direction === "LR" ? hGap : vGap);
  }

  const axis = direction === "LR" ? "height" : "width";
  const crossGap = vGap;

  const place = (id, start) => {
    const node = nodesById.get(id);
    const size = measureSubtree(id, children, nodesById, crossGap, axis);
    const kids = children.get(id) || [];
    let cursor = start;
    for (const kid of kids) {
      const kidSize = measureSubtree(kid, children, nodesById, crossGap, axis);
      place(kid, cursor);
      cursor += kidSize + crossGap;
    }
    const cross = start + (size - (direction === "LR" ? node.height : node.width)) / 2;
    const main = mainStart.get(depth.get(id) || 0) || 0;
    if (direction === "LR") {
      node.x = round(main);
      node.y = round(cross);
    } else {
      node.x = round(cross);
      node.y = round(main);
    }
  };

  let cursor = 0;
  for (const rootId of components) {
    const size = measureSubtree(rootId, children, nodesById, crossGap, axis);
    place(rootId, cursor);
    cursor += size + crossGap;
  }
  for (const node of nodes) {
    if (!Number.isFinite(node.x) || !Number.isFinite(node.y)) {
      node.x = 0;
      node.y = 0;
    }
  }
}

// Grid layout: stable reading order, N columns.
function layoutGrid(nodes, edges, options = {}) {
  if (nodes.length === 0) return;
  const hGap = Number(options.hGap) > 0 ? Number(options.hGap) : DEFAULT_H_GAP;
  const vGap = Number(options.vGap) > 0 ? Number(options.vGap) : DEFAULT_V_GAP;
  const columns = Math.max(1, Math.min(8, Number(options.columns) || Math.ceil(Math.sqrt(nodes.length))));
  const cellWidth = Math.max(...nodes.map((node) => node.width), 220);
  const cellHeight = Math.max(...nodes.map((node) => node.height), 88);
  nodes.forEach((node, index) => {
    node.x = round((index % columns) * (cellWidth + hGap));
    node.y = round(Math.floor(index / columns) * (cellHeight + vGap));
  });
  void edges;
}

function connectedComponents(nodes, edges) {
  const { neighbors } = buildGraph(nodes, edges);
  const seen = new Set();
  const components = [];
  for (const node of nodes) {
    if (seen.has(node.id)) continue;
    const stack = [node.id];
    const ids = [];
    seen.add(node.id);
    while (stack.length > 0) {
      const id = stack.pop();
      ids.push(id);
      for (const next of neighbors.get(id) || []) {
        if (!seen.has(next)) {
          seen.add(next);
          stack.push(next);
        }
      }
    }
    components.push(ids);
  }
  return components;
}

// Mind map: root in the middle, first-level branches alternating right/left,
// each side packed as a tree and mirrored horizontally for the left half.
function layoutMindmap(nodes, edges, options = {}) {
  if (nodes.length === 0) return;
  const hGap = Number(options.hGap) > 0 ? Number(options.hGap) : DEFAULT_H_GAP;
  const vGap = Number(options.vGap) > 0 ? Number(options.vGap) : DEFAULT_V_GAP;
  const nodesById = new Map(nodes.map((node) => [node.id, node]));
  const { children, parent, neighbors } = buildGraph(nodes, edges);
  const degree = new Map(nodes.map((node) => [node.id, 0]));
  for (const edge of edges) {
    if (!nodesById.has(edge.source) || !nodesById.has(edge.target)) continue;
    degree.set(edge.source, (degree.get(edge.source) || 0) + 1);
    degree.set(edge.target, (degree.get(edge.target) || 0) + 1);
  }

  const requestedRoot = options.root && nodesById.get(options.root);
  let root = requestedRoot || null;
  if (!root) {
    const rootCandidates = nodes.filter((node) => !parent.has(node.id));
    root = (rootCandidates.length > 0 ? rootCandidates : nodes)
      .slice()
      .sort((a, b) => (degree.get(b.id) || 0) - (degree.get(a.id) || 0))[0];
  }
  if (!root) return;

  const reachable = new Set();
  const stack = [root.id];
  while (stack.length > 0) {
    const id = stack.pop();
    if (reachable.has(id)) continue;
    reachable.add(id);
    for (const next of neighbors.get(id) || []) stack.push(next);
  }

  const branches = (children.get(root.id) || []).slice();
  const rest = nodes.filter((node) => !reachable.has(node.id));

  if (branches.length === 0) {
    root.x = -round(root.width / 2);
    root.y = 0;
    if (rest.length > 0) {
      layoutGrid(rest, [], { hGap, vGap, columns: Math.min(4, rest.length) });
      const minX = Math.min(...rest.map((node) => node.x));
      const top = Math.max(...rest.map((node) => node.y));
      for (const node of rest) {
        node.x = round(node.x - minX);
        node.y = round(top + root.height + vGap * 2 + (node.y - Math.min(...rest.map((item) => item.y))));
      }
    }
    return;
  }

  const right = [];
  const left = [];
  branches.forEach((id, index) => {
    if (index % 2 === 0) right.push(id);
    else left.push(id);
  });

  const layoutSide = (branchIds, sign) => {
    // Levels align across the whole side so columns stay straight.
    const depthByNode = new Map();
    const levelWidth = new Map();
    for (const branchId of branchIds) {
      const queue = [{ id: branchId, level: 0 }];
      while (queue.length > 0) {
        const { id, level } = queue.shift();
        if (depthByNode.has(id)) continue;
        depthByNode.set(id, level);
        const node = nodesById.get(id);
        levelWidth.set(level, Math.max(levelWidth.get(level) || 0, node.width));
        for (const kid of children.get(id) || []) queue.push({ id: kid, level: level + 1 });
      }
    }
    const levelStart = new Map();
    let offset = 0;
    for (const level of Array.from(levelWidth.keys()).sort((a, b) => a - b)) {
      levelStart.set(level, offset);
      offset += levelWidth.get(level) + hGap;
    }

    const heights = branchIds.map((id) => measureSubtree(id, children, nodesById, vGap, "height"));
    const total = heights.reduce((sum, height) => sum + height, 0) + vGap * (branchIds.length - 1);
    let cursor = -total / 2;

    const place = (id, start) => {
      const node = nodesById.get(id);
      const level = depthByNode.get(id) || 0;
      const size = measureSubtree(id, children, nodesById, vGap, "height");
      const kids = (children.get(id) || []).filter((kid) => depthByNode.has(kid));
      let kidCursor = start;
      for (const kid of kids) {
        const kidSize = measureSubtree(kid, children, nodesById, vGap, "height");
        place(kid, kidCursor);
        kidCursor += kidSize + vGap;
      }
      const cross = start + (size - node.height) / 2;
      const base = root.width / 2 + hGap + (levelStart.get(level) || 0);
      node.x = sign > 0 ? round(base) : round(-base - node.width);
      node.y = round(cross);
    };

    for (let index = 0; index < branchIds.length; index += 1) {
      place(branchIds[index], cursor);
      cursor += heights[index] + vGap;
    }
  };

  root.x = -round(root.width / 2);
  root.y = 0;
  layoutSide(right, 1);
  layoutSide(left, -1);

  if (rest.length > 0) {
    layoutGrid(rest, [], { hGap, vGap, columns: Math.min(4, rest.length) });
    const minX = Math.min(...rest.map((node) => node.x));
    const minY = Math.min(...rest.map((node) => node.y));
    const bottom = Math.max(...nodes.filter((node) => reachable.has(node.id)).map((node) => node.y + node.height));
    for (const node of rest) {
      node.x = round(node.x - minX);
      node.y = round(node.y - minY + bottom + vGap * 2);
    }
  }
}

function assignEdgeHandles(nodes, edges, direction) {
  const byId = new Map(nodes.map((node) => [node.id, node]));
  for (const edge of edges) {
    const source = byId.get(edge.source);
    const target = byId.get(edge.target);
    if (!source || !target) continue;
    if (direction === "TB") {
      const sourceCenter = source.y + source.height / 2;
      const targetCenter = target.y + target.height / 2;
      edge.sourceHandle = sourceCenter <= targetCenter ? "bottom" : "top";
      edge.targetHandle = sourceCenter <= targetCenter ? "top" : "bottom";
    } else {
      const sourceCenter = source.x + source.width / 2;
      const targetCenter = target.x + target.width / 2;
      edge.sourceHandle = sourceCenter <= targetCenter ? "right" : "left";
      edge.targetHandle = sourceCenter <= targetCenter ? "left" : "right";
    }
  }
}

function applyLayout(nodes, edges, options = {}) {
  const mode = options.mode || "tree";
  const direction = options.direction === "TB" ? "TB" : "LR";
  if (mode === "none") {
    const missing = nodes.filter((node) => !Number.isFinite(node.x) || !Number.isFinite(node.y));
    if (missing.length > 0) layoutGrid(missing, [], options);
    return { mode, direction };
  }
  if (mode === "grid") {
    layoutGrid(nodes, edges, options);
    return { mode, direction };
  }
  if (mode === "mindmap") {
    layoutMindmap(nodes, edges, options);
    assignEdgeHandles(nodes, edges, "LR");
    return { mode, direction: "LR" };
  }
  layoutTree(nodes, edges, options);
  assignEdgeHandles(nodes, edges, direction);
  return { mode: "tree", direction };
}

function fitViewport(nodes, groups, padding = DEFAULT_PADDING) {
  const boxes = [
    ...nodes.map((node) => ({ x: node.x, y: node.y, width: node.width, height: node.height })),
    ...groups.map((group) => ({ x: group.x, y: group.y, width: group.width, height: group.height })),
  ];
  if (boxes.length === 0) return { x: 0, y: 0, zoom: 1 };
  const minX = Math.min(...boxes.map((box) => box.x));
  const minY = Math.min(...boxes.map((box) => box.y));
  const maxX = Math.max(...boxes.map((box) => box.x + box.width));
  const maxY = Math.max(...boxes.map((box) => box.y + box.height));
  const width = maxX - minX;
  const height = maxY - minY;
  const zoom = clamp(Math.min(1.2, 900 / Math.max(1, width), 620 / Math.max(1, height)), 0.2, 1.2);
  return {
    x: round(padding - minX * zoom),
    y: round(padding - minY * zoom),
    zoom: Math.round(zoom * 100) / 100,
  };
}

module.exports = {
  DEFAULT_H_GAP,
  DEFAULT_V_GAP,
  autoNodeHeight,
  visualLength,
  applyLayout,
  layoutTree,
  layoutGrid,
  layoutMindmap,
  assignEdgeHandles,
  fitViewport,
  connectedComponents,
};
